    internal static int Region(string country) => Math.Max(0, Array.IndexOf(EsportsWorld.Countries, country));
    private static string[] Givens(int region, string gender) => gender == "女" ? Female[region] : Male[region];
    internal static int GivenCount => Male.Sum(b => b.Length) + Female.Sum(b => b.Length);
    internal static int WholeHandleCount => Handles.Sum(b => b.Length) + MaleHandles.Length + FemaleHandles.Length;
    internal static int NameCount => Enumerable.Range(0, 8).Sum(i => WorldPeople.Surnames(EsportsWorld.Countries[i]).Length * Male[i].Concat(Female[i]).Distinct().Count());
    internal static string? KnownGender(string country, string name)
    {
        int r = Region(country);
        var given = r > 2 && name.Contains('·') ? [name.Split('·')[0]]
            : WorldPeople.Surnames(country).Where(s => name.StartsWith(s, StringComparison.Ordinal)).Select(s => name[s.Length..]).ToArray();
        bool male = given.Any(Male[r].Contains), female = given.Any(Female[r].Contains);
        return male == female ? null : male ? "男" : "女";
    }
    internal static string LegalName(string country, string gender, Random random)
    {
        int r = Region(country); var given = Givens(r, gender); var families = WorldPeople.Surnames(country);
        var familyBank = random.Next(100) < (r == 2 ? 80 : 60) ? CommonFamilies[r] : families;
        string first = given[random.Next(given.Length)], last = familyBank[random.Next(familyBank.Length)];
        return r <= 2 ? last + first : first + "·" + last;
    }
    internal static string Nickname(string country, string gender, Random random)
    {
        int r = Region(country), form = random.Next(100);
        if (form < 18) return LegalName(country, gender, random);
        var bank = form < 30 ? (r == 0 ? gender == "女" ? FemaleHandles : MaleHandles : Givens(r, gender)) : Handles[r];
        string name = bank[random.Next(bank.Length)];
        return random.Next(7) == 0 && !char.IsDigit(name[^1]) ? name + (random.Next(2) == 0 ? "_" : "") + random.Next(2, 100) : name;
    }
